struct Heap<T> {
    private var a: [T] = []
    private let less: (T, T) -> Bool          // less => higher priority
    init(_ less: @escaping (T, T) -> Bool) { self.less = less }
    var count: Int { a.count }
    var top: T? { a.first }

    mutating func push(_ x: T) {
        a.append(x)
        var i = a.count - 1
        while i > 0, less(a[i], a[(i - 1) / 2]) { a.swapAt(i, (i - 1) / 2); i = (i - 1) / 2 }
    }
    @discardableResult mutating func pop() -> T? {
        guard !a.isEmpty else { return nil }
        a.swapAt(0, a.count - 1)
        let x = a.removeLast()
        var i = 0
        while true {
            let l = 2 * i + 1, r = l + 1
            var m = i
            if l < a.count, less(a[l], a[m]) { m = l }
            if r < a.count, less(a[r], a[m]) { m = r }
            if m == i { break }
            a.swapAt(i, m); i = m
        }
        return x
    }
}

struct KthLargest {
    private var heap = Heap<Int>(<)
    private let k: Int
    init(_ k: Int, _ nums: [Int]) { self.k = k; nums.forEach { _ = add($0) } }
    mutating func add(_ val: Int) -> Int {
        heap.push(val)
        if heap.count > k { heap.pop() }
        return heap.top!
    }
}
